/// <summary>
/// Data contract for importing files from Azure containers including sub-directories
/// </summary>
[DataContract]
class OMGInboundDataContract_AzureContainerSubDir extends OMGInboundDataContract_AzureContainer
{    
    OMGAzureArchiveContainer    archiveContainerName;
    OMGArchiveUnderSubDir       archiveUnderSubDir;


}

Method.Source:
[DataMember, SysOperationDisplayOrder('10'), OMGArchiveUnderSubDir]
public OMGArchiveUnderSubDir parmArchiveUnderSubDir(OMGArchiveUnderSubDir _archiveUnderSubDir = archiveUnderSubDir)
{
    archiveUnderSubDir = _archiveUnderSubDir;
    return archiveUnderSubDir;
}

[DataMember, OMGAzureArchiveContainerName, SysOperationDisplayOrder('5')]
public OMGAzureArchiveContainer parmArchiveContainerName(OMGAzureArchiveContainer _archiveContainerName = archiveContainerName)
{
    archiveContainerName = _archiveContainerName;
    return archiveContainerName;
}

/// <summary>
/// The caption used on the dialog
/// </summary>
/// <returns>A descriptive text</returns>
public Description dialogCaption()
{
    return "@OMG:ImportFromAzureContainerSubDir";
}
